@router.put('/api/documents/{doc_id}/permissions/{target_user_id}')
def update_document_permission(
    doc_id: UUID,
    target_user_id: int,
    payload: UpdatePermissionSchema,
    session: Session = Depends(get_session),
    current_user: User = Depends(get_current_user)
):
    doc = session.exec(select(Document).where(Document.id == doc_id)).first()
    if not doc or doc.owner_id != current_user.id:
        raise HTTPException(status_code=403, detail="Only document owner can modify collaborator permissions")

    perm = session.exec(
        select(DocumentPermission).where(
            DocumentPermission.document_id == doc_id,
            DocumentPermission.user_id == target_user_id
        )
    ).first()
    if not perm:
        raise HTTPException(status_code=404, detail="Permission record not found")

    perm.role = payload.role
    session.add(perm)
    session.commit()
    return {"status": "updated", "role": perm.role}
